CREATE TABLE "plugin_wattanam_academic_management_class_registration_field" ("id" TEXT PRIMARY KEY, "key" TEXT UNIQUE NOT NULL, "label" TEXT NOT NULL, "fieldType" TEXT NOT NULL DEFAULT 'TEXT', "options" JSONB, "required" BOOLEAN NOT NULL DEFAULT FALSE, "order" INTEGER NOT NULL DEFAULT 0, "enabled" BOOLEAN NOT NULL DEFAULT TRUE, "createdAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);